Item.method_code:
const { itemTypeName, getState, getLayout } = options;
const state = getState();

const updateItemsInPackage = method.getMethod('updateItemsInPackage')?.method;
if (!updateItemsInPackage) {
	return;
}

const formItems = state.grid.selectedRows
                  .filter(rowId => !item.isNew(itemTypeName, rowId))
                  .map(id => ({id, name: getLayout().grid.rows.get<string>(id, 'name') ?? id }));

await updateItemsInPackage(formItems, itemTypeName);
